func (r *GuardianRelationshipRepository) Delete(ctx context.Context, id any) error {
	ambientDB4, databaseErr4 := r.runtime.DB(ctx)
	if databaseErr4 != nil {
		return databaseErr4
	}
	query := ambientDB4.NewDelete().TableExpr(`users.student_guardian_relationships AS "relationship"`).Where(`"relationship".id = ?`, id)
	query = withTenantFilter(ctx, r.runtime, query, "relationship")
	if _, err := query.Exec(ctx); err != nil {
		return &ports.DatabaseError{Op: "delete", Err: err}
	}
	return nil
}

func (r *guardianProfileRepository) LinkAccount(ctx context.Context, profileID int64, accountID int64) error {
