func (c ClearSchoolDayHint) Validate() error {
	if c.AuthorAccountID <= 0 || c.Date.IsZero() {
		return ErrStudentNoteInvalid
	}
	if (c.SchoolClass == "") == (c.StudentID <= 0) {
		return ErrStudentNoteInvalid
	}
	return nil
}

func (n StudentNote) Edited() bool {
	return n.UpdatedAt.After(n.CreatedAt)
}

func (e *ValidationError) Error() string {
	if e == nil || e.Err == nil {
		return ""
	}
	return e.Err.Error()
}

func (e *DatabaseError) Error() string {
	if e.Err == nil {
		return "database error during " + e.Op
	}
	return "database error during " + e.Op + ": " + e.Err.Error()
}
